import{_ as o,o as t,c,a5 as r}from"./chunks/framework.DJo0M80U.js";const g=JSON.parse('{"title":"Mybatis 的参数深入","description":"","frontmatter":{"title":"Mybatis 的参数深入","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","数据库","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第五部分：数据库/02-MyBatis/Mybatis 的参数深入.md","filePath":"posts/java快速入门/第五部分：数据库/02-MyBatis/Mybatis 的参数深入.md"}'),d={name:"posts/java快速入门/第五部分：数据库/02-MyBatis/Mybatis 的参数深入.md"};function s(a,e,i,p,l,u){return t(),c("div",null,[...e[0]||(e[0]=[r('<div><p><code>3.1 parameterType</code> <strong>配置参数</strong></p><p><code>3.1.1</code></p><p><strong>使用说明</strong> 我们在上一章节中已经介绍了 <code>SQL</code> 语句传参，使用标签的 <code>parameterType</code> 属性来设定。该属性的取值可以 是基本类型，引用类型（例如<code>:String</code> 类型），还可以是实体类类型（<code>POJO</code> 类）。同时也可以使用实体类的包装 类，本章节将介绍如何使用实体类的包装类作为参数传递。传智播客——专注于 <code>Java</code>、<code>.Net</code> 和 <code>Php</code>、网页平面设计工程师的培训 3.1.2 <strong>注意事项</strong> 基 本 类 型 和 <code>String</code> 我 们 可 以 直 接 写 类 型 名 称 ， 也 可 以 使 用 包 名 <code>.</code> 类 名 的 方 式 ， 例 如 ：</p><p>java.lang.String 。 实体类类型，目前我们只能使用全限定类名。 究其原因，是 <code>mybaits</code> 在加载时已经把常用的数据类型注册了别名，从而我们在使用时可以不写包名， 而我们的是实体类并没有注册别名，所以必须写全限定类名。在今天课程的最后一个章节中将讲解如何注册实体类 的别名。 在 <code>mybatis</code> 的官方文档的说明<code>(</code>第 <code>19</code> 页<code>)</code> 这些都是支持的默认别名。我们也可以从源码角度来看它们分别都是如何定义出来的。 可以参考 <code>TypeAliasRegistery.class</code> 的源码。传智播客——专注于 <code>Java</code>、<code>.Net</code> 和 <code>Php</code>、网页平面设计工程师的培训 3.2 <strong>传递</strong> <code>pojo</code> <strong>包装对象</strong> 开发中通过 <code>pojo</code> 传递查询条件 ，查询条件是综合的查询条件，不仅包括用户查询条件还包括其它的查 询条件（比如将用户购买商品信息也作为查询条件），这时可以使用包装对象传递输入参数。</p><p><code>Pojo</code></p><p>类中包含 <code>pojo</code>。 需求：根据用户名查询用户信息，查询条件放到 <code>QueryVo</code> 的 <code>user</code> 属性中。</p><p><code>3.2.1</code></p><p><strong>编写</strong></p><p>QueryVo /** *</p><ul><li>&lt;p&gt;Title: QueryVo&lt;/p&gt;</li><li>&lt;p&gt;Description: 查询条件对象</li></ul><p>&lt;/p&gt;</p><ul><li>&lt;p&gt;Company: <a href="http://www.itheima.com/" target="_blank" rel="noreferrer">http://www.itheima.com/</a> &lt;/p&gt; */ public class QueryVo implements Serializable { private User user; public User getUser() { return user; } public void setUser(User user) { this.user = user; } } 传智播客——专注于 <code>Java</code>、<code>.Net</code> 和 <code>Php</code>、网页平面设计工程师的培训 3.2.2 <code>**编写持久层接口**</code></li></ul><p>/** *</p><ul><li>&lt;p&gt;Title: IUserDao&lt;/p&gt;</li><li>&lt;p&gt;Description: <code>用户的业务层接口</code> &lt;/p&gt;</li><li>&lt;p&gt;Company: <a href="http://www.itheima.com/" target="_blank" rel="noreferrer">http://www.itheima.com/</a> &lt;/p&gt; <em>/ public interface IUserDao { /</em>*</li><li></li></ul><p><code>根据 </code>QueryVo<code> 中的条件查询用户</code></p><ul><li>@param vo</li><li>@return */ List&lt;User&gt; findByVo(QueryVo vo); } 3.2.3 <code>**持久层接口的映射文件**</code></li></ul><p>&lt;!-- <code>根据用户名称模糊查询，参数变成一个 </code>QueryVo<code> 对象了</code> --&gt; &lt;select id=&quot;findByVo&quot; resultType=&quot;com.itheima.domain.User&quot; parameterType=&quot;com.itheima.domain.QueryVo&quot;&gt; select * from user where username like #{user.username}; &lt;/select&gt; 3.2.4 <code>**测试包装类作为参数**</code></p><p>@Test public void testFindByQueryVo() { QueryVo vo = new QueryVo(); User user = new User(); user.setUserName(&quot;% <code>王</code> %&quot;); vo.setUser(user); List&lt;User&gt; users = userDao.findByVo(vo); for(User u : users) { System.out.println(u); } } 传智播客——专注于 <code>Java</code>、<code>.Net</code> 和 <code>Php</code>、网页平面设计工程师的培训 `</p></div>',1)])])}const m=o(d,[["render",s]]);export{g as __pageData,m as default};
